      "tipo": "GC",
      "causa_raiz": "Concatenação contínua de strings em loop ('s += i.ToString()') e alocação recorrente de arrays ('new object[10000]') dentro do método Update(). No C#, strings são imutáveis; cada concatenação e chamada a ToString gera um novo objeto temporário no Heap. Isso totaliza mais de 8 MB alocados por frame, acionando coletas de lixo frequentes (Garbage Collector) que travam a thread principal por até 24.57 ms, excedendo o orçamento de 16.7 ms.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private readonly StringBuilder _stringBuilder = new StringBuilder(4096);
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");
        private MaterialPropertyBlock _propertyBlock;

        private void Awake()
        {
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;

            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _stringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _stringBuilder.Append(i);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials && clone.TryGetComponent<Renderer>(out var renderer))
            {
                renderer.GetPropertyBlock(_propertyBlock);
                _propertyBlock.SetColor(ColorPropertyId, new Color(
                    UnityEngine.Random.value,
                    UnityEngine.Random.value,
                    UnityEngine.Random.value));
                renderer.SetPropertyBlock(_propertyBlock);
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, o texto (string) não pode ser modificado após ser criado. Toda vez que você usa '+' para juntar texto repetidamente ou chama '.ToString()', o computador cria um objeto descartável na memória Heap. O Garbage Collector precisa parar o jogo para limpar essa montanha de lixo, causando congelamentos de tela (stuttering). Ao usar StringBuilder e evitar alocar novos objetos a cada quadro dentro do Update(), mantemos a memória limpa e a taxa de quadros fluida."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Uso repetitivo de 'GameObject.FindObjectsOfType<GameObject>()' dentro do laço de execução do Update(). Essa função varre recursivamente toda a árvore de objetos e componentes da cena ativa, além de alocar um array no Heap a cada chamada. Executada em loops de até 512 iterações por frame, ela sobrecarrega o processador central (levando o tempo de CPU a picos de 380 ms).",
      "codigo_refatorado": "// Para otimizar varreduras na CPU, evite buscas globais repetitivas.
// Em vez de invocar GameObject.FindObjectsOfType no Update, mantenha um registro ou lista estática:
// Exemplo de padrão Registry:
/*
public static class TrackedObjects
{
    public static readonly List<GameObject> Active = new List<GameObject>(1024);
}

// Em cada objeto que precisa ser monitorado:
private void OnEnable() => TrackedObjects.Active.Add(gameObject);
private void OnDisable() => TrackedObjects.Active.Remove(gameObject);
*/",
      "explicacao_didatica": "Chamar 'FindObjectsOfType' dentro do Update é o equivalente a pedir para alguém ler um catálogo telefônico inteiro procurando nomes 60 vezes por segundo. O processador gasta todo o seu poder de cálculo apenas procurando objetos em vez de processar a física e a lógica do jogo. A solução correta é fazer com que os objetos se apresentem e se registrem quando surgem na cena, permitindo acesso imediato sem buscas pesadas."
    }
  ],
  "dicas_level_design": null
}

